              lat: "Español (Latino)", latino: "Español (Latino)",
              "es-lat": "Español (Latino)", "es-es": "Español (Castellano)",
              eng: "Inglés", en: "Inglés", ingles: "Inglés",
              jpn: "Japonés", ja: "Japonés", jap: "Japonés", japones: "Japonés",
              por: "Portugués", pt: "Portugués", kor: "Coreano", ko: "Coreano",
              fra: "Francés", fr: "Francés", ita: "Italiano", it: "Italiano",
